package com.lifeos.habits; import com.lifeos.shared.AuditableEntity;import com.lifeos.users.User;import jakarta.persistence.*;
@Entity @Table(name="habits") public class Habit extends AuditableEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=150)private String name;@Column(columnDefinition="text")private String description;@Enumerated(EnumType.STRING)@Column(nullable=false)private HabitFrequency frequency;@Column(nullable=false)private Integer targetPerWeek;@Column(nullable=false)private Integer currentStreak=0;@Column(nullable=false)private Integer longestStreak=0;@Column(nullable=false)private boolean active=true;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public HabitFrequency getFrequency(){return frequency;}public void setFrequency(HabitFrequency v){frequency=v;}public Integer getTargetPerWeek(){return targetPerWeek;}public void setTargetPerWeek(Integer v){targetPerWeek=v;}public Integer getCurrentStreak(){return currentStreak;}public void setCurrentStreak(Integer v){currentStreak=v;}public Integer getLongestStreak(){return longestStreak;}public void setLongestStreak(Integer v){longestStreak=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public void setUser(User v){user=v;}}
